1	//! Harness stream: a realtime view of one harness run's raw output, pretty
2	//! formatted and monospace with JSON highlighting, just the text with no border
3	//! or decoration. It follows the newest line while scrolled to the bottom, and
4	//! leaves the view alone while scrolled up. A stream follows the run in
5	//! progress when it opens, and each run that starts after it, one after the
6	//! other.
7	
8	use gpui_kit::component::input::{Editor, EditorState};
9	use gpui_kit::*;
10	
11	use crate::harness_run::{HarnessRun, HarnessRuns};
12	
13	pub struct HarnessStream {
14	    editor: Entity<EditorState>,
15	    run: Option<Entity<HarnessRun>>,
16	    /// How many of the run's lines the editor already shows.
17	    shown: usize,
18	    /// How many rows the editor's text spans.
19	    rows: usize,
20	    /// New lines arrived that the view has not scrolled to yet.
21	    follow_pending: bool,
22	    _runs: Subscription,
23	    _run: Option<Subscription>,
24	}
25	
26	impl HarnessStream {
27	    pub fn new(window: &mut Window, cx: &mut Context<Self>) -> Self {
28	        let editor = cx.new(|cx| {
29	            EditorState::new(window, cx)
30	                .language("json")
31	                .line_number(false)
32	                .folding(false)
33	                // One row per output line, so the newest line's position is
34	                // known without the editor's private wrap layout.
35	                .soft_wrap(false)
36	                .placeholder("Waiting for the next run…")
37	        });
38	
39	        // Each run that starts is followed in turn, its output after the last's.
40	        let runs = cx.observe_global_in::<HarnessRuns>(window, |this, window, cx| {
41	            if let Some(run) = HarnessRuns::in_progress(cx)
42	                && this.run.as_ref() != Some(&run)
43	            {
44	                this.attach(run, window, cx);
45	            }
46	        });
47	        let mut this = Self {
48	            editor,
49	            run: None,
50	            shown: 0,
51	            rows: 0,
52	            follow_pending: false,
53	            _runs: runs,
54	            _run: None,
55	        };
56	        if let Some(run) = HarnessRuns::in_progress(cx) {
57	            this.attach(run, window, cx);
58	        }
59	        this
60	    }
61	
62	    fn attach(&mut self, run: Entity<HarnessRun>, window: &mut Window, cx: &mut Context<Self>) {
63	        // Anything the previous run still had is shown before moving on.
64	        self.show_new_lines(window, cx);
65	        self._run = Some(cx.observe_in(&run, window, |this, _, window, cx| {
66	            this.show_new_lines(window, cx)
67	        }));
68	        self.run = Some(run);
69	        self.shown = 0;
70	        self.show_new_lines(window, cx);
71	    }
72	
73	    /// Appends the run's lines the editor does not show yet. If the view was
74	    /// at the bottom, it scrolls to them once the editor has laid them out;
75	    /// otherwise auto scroll waits until the user scrolls back down.
76	    fn show_new_lines(&mut self, window: &mut Window, cx: &mut Context<Self>) {
77	        let Some(run) = &self.run else {
78	            return;
79	        };
80	        let lines = run.read(cx).lines();
81	        let mut text = String::new();
82	        for line in lines.iter().skip(self.shown) {
83	            // A blank line between events, whichever run they came from.
84	            if self.rows > 0 || !text.is_empty() {
85	                text.push_str("\n\n");
86	            }
87	            text.push_str(&pretty(line));
88	        }
89	        self.shown = lines.len();
90	
91	        if !text.is_empty() {
92	            // Measured before the new rows count, against the text on screen.
93	            // A scroll still pending keeps following.
94	            self.follow_pending = self.follow_pending || self.is_at_bottom(cx);
95	            // Soft wrap is off, so each line of text is one row; only the
96	            // first text appended opens a row without a line break.
97	            self.rows = self.rows.max(1) + text.matches('\n').count();
98	            let follow = self.follow_pending;
99	            self.editor.update(cx, |editor, cx| {
100	                // Moving the cursor to the end scrolls to it: keep the view
101	                // where the user left it unless following.
102	                let offset = editor.scroll_offset();
103	                let end = editor.value().len();
104	                editor.set_selected_range(end..end, cx);
105	                editor.insert(text, window, cx);
106	                if !follow {
107	                    editor.set_scroll_offset(offset, cx);
108	                }
109	            });
110	        }
111	        cx.notify();
112	    }
113	
114	    /// Whether the view shows the last line of the text it holds. Before the
115	    /// editor is laid out there is nothing to scroll away from, so it is.
116	    fn is_at_bottom(&self, cx: &App) -> bool {
117	        let editor = self.editor.read(cx);
118	        let (Some(line_height), Some(bounds)) = (editor.line_height(), editor.text_bounds()) else {
119	            return true;
120	        };
121	        let bottom = (bounds.size.height - line_height * self.rows as f32).min(px(0.));
122	        editor.scroll_offset().y <= bottom + px(1.)
123	    }
124	
125	    /// Scrolls so the last line sits at the bottom of the view, returning
126	    /// whether the editor had been laid out to do so. The editor only scrolls
127	    /// to its cursor while focused, and a stream never is.
128	    fn scroll_to_newest(&mut self, cx: &mut Context<Self>) -> bool {
129	        let rows = self.rows;
130	        self.editor.update(cx, |editor, cx| {
131	            let (Some(line_height), Some(bounds)) = (editor.line_height(), editor.text_bounds())
132	            else {
133	                return false;
134	            };
135	            let bottom = (bounds.size.height - line_height * rows as f32).min(px(0.));
136	            let x = editor.scroll_offset().x;
137	            editor.set_scroll_offset(point(x, bottom), cx);
138	            true
139	        })
140	    }
141	}
142	
143	/// One line of output, indented across lines if it is JSON, else as it is.
144	fn pretty(line: &str) -> String {
145	    serde_json::from_str::<serde_json::Value>(line)
146	        .ok()
147	        .and_then(|value| serde_json::to_string_pretty(&value).ok())
148	        .unwrap_or_else(|| line.to_string())
149	}
150	
151	impl Render for HarnessStream {
152	    fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
153	        // Painted after the editor, so its layout of any new lines is known:
154	        // scroll to them then. Only new output scrolls, so the stream can
155	        // always be scrolled by hand.
156	        let this = cx.entity().downgrade();
157	        let follow_newest = canvas(
158	            |_, _, _| {},
159	            move |_, _, _, cx| {
160	                this.update(cx, |this, cx| {
161	                    if this.follow_pending && this.scroll_to_newest(cx) {
162	                        this.follow_pending = false;
163	                    }
164	                })
165	                .ok();
166	            },
167	        )
168	        .absolute()
169	        .size_full();
170	
171	        div()
172	            .relative()
173	            .size_full()
174	            .child(
175	                Editor::new(&self.editor)
176	                    .readonly(true)
177	                    // Just the text: no border or background.
178	                    .appearance(false)
179	                    .h(relative(1.)),
180	            )
181	            .child(follow_newest)
182	    }
183	}
184	
185	#[cfg(test)]
186	mod tests {
187	    // Explicit imports: globbing `gpui_kit::*` would bring in GPUI's `test`
188	    // macro and shadow Rust's `#[test]`.
189	    use std::time::Duration;
190	
191	    use gpui_kit::component::Root;
192	    use gpui_kit::test::{TestAppContextExt as _, TestWindowExt as _};
193	    use gpui_kit::{AppContext as _, TestAppContext};
194	
195	    use super::{HarnessStream, pretty};
196	    use crate::harness_run::HarnessRuns;
197	
198	    /// JSON is indented across lines; anything else is left as it arrived.
199	    #[test]
200	    fn pretty_formats_json_lines() {
201	        assert_eq!(
202	            pretty(r#"{"type":"result","ok":true}"#),
203	            "{\n  \"type\": \"result\",\n  \"ok\": true\n}"
204	        );
205	        assert_eq!(pretty("not json {"), "not json {");
206	    }
207	
208	    /// A stream left open follows each run that starts, after the last one's
209	    /// output.
210	    #[gpui_kit::test]
211	    async fn follows_every_run_that_starts(cx: &mut TestAppContext) {
212	        cx.update(|cx| {
213	            gpui_kit::init(cx);
214	            HarnessRuns::init(cx);
215	        });
216	        let mut stream = None;
217	        cx.add_window(|window, cx| {
218	            let view = cx.new(|cx| HarnessStream::new(window, cx));
219	            stream = Some(view.clone());
220	            Root::new(view, window, cx)
221	        });
222	        let stream = stream.unwrap();
223	        let editor = stream.read_with(cx, |stream, _| stream.editor.clone());
224	
225	        for line in ["first", "second"] {
226	            let run = cx.update(HarnessRuns::start);
227	            cx.update(|cx| {
228	                run.update(cx, |run, cx| {
229	                    run.push_line(line.to_string(), cx);
230	                    run.finish(cx);
231	                })
232	            });
233	            cx.run_until_parked();
234	        }
235	
236	        let text = editor.read_with(cx, |editor, _| editor.value().to_string());
237	        assert_eq!(text, "first\n\nsecond");
238	    }
239	
240	    /// A stream opened between runs follows the next run, shows each line
241	    /// pretty formatted as it arrives, and keeps the newest line in view.
242	    #[gpui_kit::test]
243	    async fn follows_the_next_run_to_its_newest_line(cx: &mut TestAppContext) {
244	        cx.update(|cx| {
245	            gpui_kit::init(cx);
246	            HarnessRuns::init(cx);
247	        });
248	        let mut stream = None;
249	        let window = cx.add_window(|window, cx| {
250	            let view = cx.new(|cx| HarnessStream::new(window, cx));
251	            stream = Some(view.clone());
252	            Root::new(view, window, cx)
253	        });
254	        let stream = stream.unwrap();
255	        let handle = window.into();
256	
257	        let run = cx.update(HarnessRuns::start);
258	        let lines: Vec<String> = (0..80)
259	            .map(|ix| format!("{{\"type\":\"stream_event\",\"index\":{ix}}}"))
260	            .collect();
261	        cx.update(|cx| {
262	            run.update(cx, |run, cx| {
263	                for line in &lines {
264	                    run.push_line(line.clone(), cx);
265	                }
266	            })
267	        });
268	
269	        let editor = stream.read_with(cx, |stream, _| stream.editor.clone());
270	        let attached = stream.read_with(cx, |stream, _| stream.run.is_some());
271	        assert!(attached, "the stream did not follow the run that started");
272	
273	        let expected = lines
274	            .iter()
275	            .map(|line| pretty(line))
276	            .collect::<Vec<_>>()
277	            .join("\n\n");
278	        cx.wait_for(handle, Duration::from_secs(2), |_, cx| {
279	            editor.read(cx).value().len() == expected.len()
280	        })
281	        .await;
282	        let text = editor.read_with(cx, |editor, _| editor.value().to_string());
283	        assert_eq!(text, expected);
284	        let rows = expected.lines().count();
285	        assert_eq!(stream.read_with(cx, |stream, _| stream.rows), rows);
286	
287	        // Let the editor lay out the new text, then the stream scroll to it.
288	        for _ in 0..3 {
289	            cx.run_until_parked();
290	            cx.update_window(handle, |_, window, cx| window.render_frame(cx))
291	                .unwrap();
292	        }
293	        let (offset, bounds, line_height) = editor.read_with(cx, |editor, _| {
294	            (
295	                editor.scroll_offset(),
296	                editor.text_bounds(),
297	                editor.line_height(),
298	            )
299	        });
300	        let (bounds, line_height) = (bounds.unwrap(), line_height.unwrap());
301	        let content = line_height * rows as f32;
302	        assert!(
303	            offset.y < gpui_kit::px(0.),
304	            "the stream is not scrolled: offset {offset:?}, text bounds {bounds:?}"
305	        );
306	        assert!(
307	            content + offset.y <= bounds.size.height + line_height,
308	            "the newest line is below the view: offset {offset:?}, {content:?} of content \
309	             in {bounds:?}"
310	        );
311	
312	        let push = |from: usize, cx: &mut TestAppContext| {
313	            cx.update(|cx| {
314	                run.update(cx, |run, cx| {
315	                    for ix in from..from + 20 {
316	                        run.push_line(format!("{{\"index\":{ix}}}"), cx);
317	                    }
318	                })
319	            });
320	            for _ in 0..3 {
321	                cx.run_until_parked();
322	                cx.update_window(handle, |_, window, cx| window.render_frame(cx))
323	                    .unwrap();
324	            }
325	        };
326	
327	        // Scrolled up, new output leaves the view where it is.
328	        cx.update(|cx| {
329	            editor.update(cx, |editor, cx| {
330	                editor.set_scroll_offset(gpui_kit::point(gpui_kit::px(0.), gpui_kit::px(0.)), cx)
331	            })
332	        });
333	        push(80, cx);
334	        let offset = editor.read_with(cx, |editor, _| editor.scroll_offset());
335	        assert_eq!(offset.y, gpui_kit::px(0.), "auto scroll was not suspended");
336	
337	        // Back at the bottom, it follows new output again.
338	        stream.update(cx, |stream, cx| {
339	            stream.scroll_to_newest(cx);
340	        });
341	        push(100, cx);
342	        let (offset, rows) = stream.read_with(cx, |stream, cx| {
343	            (editor.read(cx).scroll_offset(), stream.rows)
344	        });
345	        let content = line_height * rows as f32;
346	        assert!(
347	            content + offset.y <= bounds.size.height + line_height,
348	            "auto scroll did not resume at the bottom: offset {offset:?}, {content:?} of \
349	             content in {bounds:?}"
350	        );
351	    }
352	}
